import socket

def task_func(myString, API_KEY):
    # Extract all URLs from the string using regex
    url_pattern = r'https?://[^\s<>"{}|\\^`\[\]]+'
    urls = re.findall(url_pattern, myString)

    # Extract domains from URLs
    domains = set()
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url)
            domain = parsed.netloc
            # Remove port if present
            if ':' in domain:
                domain = domain.split(':')[0]
            # Remove 'www.' if present
            if domain.startswith('www.'):
                domain = domain[4:]
            if domain:
                domains.add(domain)
        except Exception:
            continue

    # Get geolocation data for each domain
    result = {}
    for domain in domains:
        try:
            # Resolve domain to IP address
            ip_address = socket.gethostbyname(domain)

            # Use IP API to get geolocation data
            # ip-api.com is used here; API_KEY is included per function signature
            response = requests.get(f'http://ip-api.com/json/{ip_address}', timeout=10)
            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    result[domain] = data
                else:
                    result[domain] = None
            else:
                result[domain] = None
        except Exception:
            result[domain] = None

    return result

