import re

def task_func(json_dir_path, word_count):
    def extract_text_from_json(data):
        """Recursively extract all string values from JSON data"""
        text_parts = []
        if isinstance(data, str):
            return data
        elif isinstance(data, dict):
            for value in data.values():
                text_parts.append(extract_text_from_json(value))
        elif isinstance(data, list):
            for item in data:
                text_parts.append(extract_text_from_json(item))
        return ' '.join(text_parts)

    def tokenize_text(text):
        """Tokenize text into lowercase alphabetic words"""
        text = text.lower()
        return re.findall(r'\b[a-z]+\b', text)

    all_words = []

    # Iterate through all files in the directory
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    text = extract_text_from_json(data)
                    words = tokenize_text(text)
                    all_words.extend(words)
            except (json.JSONDecodeError, IOError, Exception):
                continue

    # Count word frequencies
    word_counter = Counter(all_words)

    # Get the most common words
    most_common = word_counter.most_common(word_count)

    return most_common

