def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    # Check if file exists
    if not os.path.exists(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    # Load JSON file
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format: {e}")

    # Ensure the JSON is a dictionary
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    # Check required fields
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Required field missing: {field}")

    # Validate types for each property defined in the schema
    properties = INPUT_JSON.get("properties", {})
    for field, schema in properties.items():
        if field in data:
            expected_type = schema.get("type")
            if not isinstance(data[field], expected_type):
                raise ValueError(
                    f"Type mismatch for field '{field}': expected {expected_type.__name__}, got {type(data[field]).__name__}"
                )

    # Validate email format if email field exists
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError(f"Invalid email format: {data['email']}")

    # Check if the requested attribute exists
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")

    # Return the specified attribute value
    return data[attribute]

