def task_func(directory, string):
    # Find all JSON files recursively in the directory and subdirectories
    json_files = glob(os.path.join(directory, '**', '*.json'), recursive=True)

    matching_files = []

    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)

            # Search for string in JSON structure
            if search_in_json(data, string):
