def search_in_json(data, string):
    """Recursively search for string in JSON data structure (case-sensitive)"""
    if isinstance(data, str):
        return string in data
    elif isinstance(data, dict):
        for key, value in data.items():
            # Search in both keys and values
            if string in key or search_in_json(value, string):
                return True
        return False
    elif isinstance(data, list):
        for item in data:
            if search_in_json(item, string):
                return True
        return False
    else:
        # For other types (int, float, bool, None), no string match possible
        return False

