def task_func(json_str):
    # Handle empty or invalid input
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        # Load JSON string into dictionary
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    # Check if data is a dictionary
    if not isinstance(data, dict):
        return pd.DataFrame()

    # Check if dictionary is empty
    if not data:
        return pd.DataFrame()

    # Normalize the dictionary by doubling numerical values
    normalized_data = {}

    for key, value in data.items():
        if isinstance(value, (int, float)):
            # Single numerical value
            normalized_data[key] = float(value * 2)
        elif isinstance(value, list):
            # List of values
            normalized_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    normalized_list.append(float(item * 2))
                elif isinstance(item, str):
                    # Try to extract number from string
                    match = re.search(r'-?\d+\.?\d*', item)
                    if match:
                        num = float(match.group())
                        normalized_list.append(float(num * 2))
                    else:
                        normalized_list.append(item)
                else:
                    normalized_list.append(item)
            normalized_data[key] = normalized_list
        elif isinstance(value, str):
            # String that might contain a number
            match = re.search(r'-?\d+\.?\d*', value)
            if match:
                num = float(match.group())
                normalized_data[key] = float(num * 2)
            else:
                normalized_data[key] = value
        else:
            # Other types (including nested dicts - not processed)
            normalized_data[key] = value

    # Create DataFrame from the normalized dictionary
    try:
        df = pd.DataFrame([normalized_data])
        return df
    except Exception:
        return pd.DataFrame()

