# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]

def task_func(directory):
    # Initialize counts for each prefix
    prefix_counts = {prefix: 0 for prefix in PREFIXES}

    def count_keys(data):
        """Recursively count keys that match the prefixes"""
        if isinstance(data, dict):
            for key in data.keys():
                # Check if key starts with any of the prefixes
                for prefix in PREFIXES:
                    if key.startswith(prefix):
                        prefix_counts[prefix] += 1

                # Recursively check nested structures
                count_keys(data[key])

        elif isinstance(data, list):
            # Check each item in the list
            for item in data:
                count_keys(item)

    # Iterate through all files in the directory
    for filename in os.listdir(directory):
        # Check if file has .json extension
        if filename.endswith('.json'):
            filepath = os.path.join(directory, filename)

            try:
                # Read and parse the JSON file
                with open(filepath, 'r', encoding='utf-8') as f:
                    data = json.load(f)

                # Count keys with matching prefixes
                count_keys(data)
            except (json.JSONDecodeError, IOError, OSError):
                # Skip files that can't be read or parsed
                continue

    return prefix_counts

